static int64_t df_sat_i64_r(double v) {
  if (isnan(v)) return 0;
  if (v <= -9223372036854775808.0) return INT64_MIN;
  if (v >= 9223372036854775807.0) return INT64_MAX;
  return (int64_t)v;
}
static uint64_t df_sat_u64_i(int64_t v) { return v < 0 ? 0 : (uint64_t)v; }
